/**
 * WhisperDrive Browser Injection PoC
 * Educational/Ethical Red Team Demonstration
 * 
 * Usage:
 * - Chromium Dev Console: javascript: (function () {/*paste code here*/ })();
 * - Browser Extension: Add to content_scripts in manifest.json
 */

interface MetadataSimulation {
  filename: string;
  shared_with: string[];
  modified: string;
  accessLevel: string;
}

class WhisperDriveInjector {
  private logPrefix = '[WhisperDrive]';
  private simulatedEndpoints = [
    '/api/files/metadata/root',
    '/api/users/self',
    '/api/sharing/activity'
  ];

  constructor() {
    this.initialize();
  }

  private initialize(): void {
    try {
      this.injectOverlay();
      this.simulateMetadataHarvest();
      this.logEthicalWarning();
    } catch (error) {
      console.error(`${this.logPrefix} Initialization failed:`, error);
    }
  }

  private injectOverlay(): void {
    const overlay = document.createElement('div');
    overlay.id = 'whisperdrive-overlay';
    overlay.style.cssText = `
      position: fixed;
      bottom: 10px;
      right: 10px;
      background: rgba(0,0,0,0.8);
      color: #0f0;
      padding: 10px;
      font-family: monospace;
      font-size: 12px;
      z-index: 999999;
      border: 1px solid #0f0;
      border-radius: 4px;
    `;
    overlay.innerHTML = `
      <div><strong>WhisperDrive POC</strong></div>
      <div>Status: <span style="color:lime">SIMULATION MODE</span></div>
      <div>Auth Verification: <span style="color:orange">BYPASSED (Simulated)</span></div>
      <div>File Access: <span style="color:orange">NOT ATTEMPTED</span></div>
    `;

    document.body.appendChild(overlay);
    console.log(`${this.logPrefix} Overlay injected`);
  }

  private simulateMetadataHarvest(): void {
    const mockData: MetadataSimulation = {
      filename: '2025-Q3-Budget.xlsx',
      shared_with: ['alice@example.com', 'bob@example.com'],
      modified: '7 days ago',
      accessLevel: 'viewer'
    };

    this.simulatedEndpoints.forEach((endpoint) => {
      console.log(`${this.logPrefix} Harvesting from: ${endpoint}`, mockData);
    });
  }

  private logEthicalWarning(): void {
    console.warn(`
═══════════════════════════════════════════════════════════
${this.logPrefix} ETHICAL NOTICE
═══════════════════════════════════════════════════════════

This is a PoC for EDUCATIONAL purposes only. 

Key vulnerabilities demonstrated:
  • Authorization model is permissive and trusts client-side signals
  • OAuth tokens stored insecurely in browser storage
  • No validation of session authenticity
  • Privileges were "handed to you at the door" — not escalated

This is NOT an exploit — it's a design flaw made demonstrable.

NEVER use against systems you don't own or lack permission for.
═══════════════════════════════════════════════════════════
    `);
  }
}

// Auto-initialize when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => new WhisperDriveInjector());
} else {
  new WhisperDriveInjector();
}

