// Red Team Cloud Metadata Reconnaissance Module
// Targets: Dropbox, Google Drive, OneDrive, Box, Slack (adaptable)
// Purpose: Harvest file/folder/org metadata using de-escalated API tokens

class MetadataReconModule {
    constructor(service, token) {
        this.service = service;
        this.token = token;
        this.headers = this._buildHeaders();
        this.endpoints = this._defineEndpoints();
    }

    _buildHeaders() {
        switch (this.service) {
            case 'dropbox':
                return {
                    'Authorization': `Bearer ${this.token}`,
                    'Content-Type': 'application/json'
                };
            case 'gdrive':
                return {
                    'Authorization': `Bearer ${this.token}`
                };
            case 'onedrive':
                return {
                    'Authorization': `Bearer ${this.token}`
                };
            default:
                throw new Error('Unsupported service');
        }
    }

    _defineEndpoints() {
        switch (this.service) {
            case 'dropbox':
                return {
                    list: 'https://api.dropboxapi.com/2/files/list_folder',
                    shared: 'https://api.dropboxapi.com/2/sharing/list_folders'
                };
            case 'gdrive':
                return {
                    list: 'https://www.googleapis.com/drive/v3/files'
                };
            case 'onedrive':
                return {
                    list: 'https://graph.microsoft.com/v1.0/me/drive/root/children'
                };
        }
    }

    async listMetadata() {
        const res = await fetch(this.endpoints.list, {
            method: 'POST',
            headers: this.headers,
            body: this.service === 'dropbox' ? JSON.stringify({ path: '' }) : null
        });

        if (!res.ok) throw new Error(`Metadata fetch failed: ${res.status}`);

        const data = await res.json();
        return data;
    }

    // Optional: Enumerate shared folders, org metadata, user roles
    async listShared() {
        if (!this.endpoints.shared) return null;

        const res = await fetch(this.endpoints.shared, {
            method: 'POST',
            headers: this.headers,
            body: '{}'
        });

        if (!res.ok) throw new Error(`Shared metadata fetch failed: ${res.status}`);

        return await res.json();
    }
}

// Example usage:
// const recon = new MetadataReconModule('dropbox', YOUR_TOKEN);
// recon.listMetadata().then(console.log);

