 * Supported Services: Dropbox, Google Drive, OneDrive
 * Purpose: Demonstrate metadata access risks using de-escalated OAuth tokens
 */

class MetadataReconModule {
    static SUPPORTED_SERVICES = ['dropbox', 'gdrive', 'onedrive'];

    static ENDPOINTS = {
        dropbox: {
            list: 'https://api.dropboxapi.com/2/files/list_folder',
            shared: 'https://api.dropboxapi.com/2/sharing/list_folders',
            users: 'https://api.dropboxapi.com/2/users/get_current_account'
        },
        gdrive: {
            list: 'https://www.googleapis.com/drive/v3/files'
        },
        onedrive: {
            list: 'https://graph.microsoft.com/v1.0/me/drive/root/children',
            users: 'https://graph.microsoft.com/v1.0/me'
        }
    };

    constructor(service, token) {
        if (!token || typeof token !== 'string') {
            throw new Error('Token must be a non-empty string');
        }

        if (!MetadataReconModule.SUPPORTED_SERVICES.includes(service)) {
            throw new Error(`Unsupported service: ${service}. Supported: ${MetadataReconModule.SUPPORTED_SERVICES.join(', ')}`);
        }

        this.service = service;
        this.token = token;
        this.timeout = 10000; // 10s timeout
        this.logger = this._createLogger();
    }

    _createLogger() {
        const prefix = `[MetadataRecon:${this.service}]`;
        return {
            info: (...args) => console.log(prefix, ...args),
            warn: (...args) => console.warn(prefix, ...args),
            error: (...args) => console.error(prefix, ...args)
        };
    }

    _buildHeaders() {
        return {
            'Authorization': `Bearer ${this.token}`,
            'Content-Type': 'application/json',
            'User-Agent': 'MetadataReconModule/1.0'
        };
    }

    _validateEndpoint(url) {
        try {
            const parsed = new URL(url);
            if (parsed.protocol !== 'https:') {
                throw new Error('Only HTTPS endpoints allowed');
            }
            return true;
        } catch (error) {
            throw new Error(`Invalid endpoint URL: ${error.message}`);
        }
    }

    async _fetchWithTimeout(url, options) {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), this.timeout);

        try {
            const response = await fetch(url, { ...options, signal: controller.signal });
            clearTimeout(timeoutId);
            return response;
        } catch (error) {
            clearTimeout(timeoutId);
            if (error.name === 'AbortError') {
                throw new Error(`Request timeout after ${this.timeout}ms`);
            }
            throw error;
        }
    }

    async listMetadata(options = {}) {
        try {
            const endpoint = MetadataReconModule.ENDPOINTS[this.service]?.list;
            if (!endpoint) {
                throw new Error(`No list endpoint defined for ${this.service}`);
            }

            this._validateEndpoint(endpoint);
            this.logger.info(`Fetching metadata from ${endpoint}`);

            const body = this.service === 'dropbox' 
                ? JSON.stringify({ path: options.path || '' })
                : null;

            const response = await this._fetchWithTimeout(endpoint, {
                method: this.service === 'dropbox' ? 'POST' : 'GET',
                headers: this._buildHeaders(),
                body
            });

            if (!response.ok) {
                throw new Error(`API error ${response.status}: ${response.statusText}`);
            }

            const data = await response.json();
            this.logger.info('Metadata retrieved successfully');
            return data;
        } catch (error) {
            this.logger.error('listMetadata failed:', error.message);
            throw error;
        }
    }

    async listShared() {
        try {
            const endpoint = MetadataReconModule.ENDPOINTS[this.service]?.shared;
            if (!endpoint) {
                this.logger.warn(`No shared endpoint defined for ${this.service}`);
                return null;
            }

            this._validateEndpoint(endpoint);
            this.logger.info(`Fetching shared items from ${endpoint}`);

            const response = await this._fetchWithTimeout(endpoint, {
                method: 'POST',
                headers: this._buildHeaders(),
                body: '{}'
            });

            if (!response.ok) {
                throw new Error(`API error ${response.status}: ${response.statusText}`);
            }

            const data = await response.json();
            this.logger.info('Shared items retrieved successfully');
            return data;
        } catch (error) {
            this.logger.error('listShared failed:', error.message);
            throw error;
        }
    }

    async getUser() {
        try {
            const endpoint = MetadataReconModule.ENDPOINTS[this.service]?.users;
            if (!endpoint) {
                this.logger.warn(`No user endpoint defined for ${this.service}`);
                return null;
            }

            this._validateEndpoint(endpoint);
            this.logger.info(`Fetching user profile from ${endpoint}`);

            const response = await this._fetchWithTimeout(endpoint, {
                method: 'GET',
                headers: this._buildHeaders()
            });

            if (!response.ok) {
                throw new Error(`API error ${response.status}: ${response.statusText}`);
            }

            const data = await response.json();
            this.logger.info('User profile retrieved successfully');
            return data;
        } catch (error) {
            this.logger.error('getUser failed:', error.message);
            throw error;
        }
    }
}

