(function WhisperDrivePOC() {
    const LOG_PREFIX = '[WhisperDrive]';

    /**
     * Safely extract tokens from browser storage
     * NO EXFILTRATION - for analysis only
     */
    const harvestTokens = () => {
        try {
            const tokens = {};

            // Collect from localStorage
            for (let i = 0; i < localStorage.length; i++) {
                const key = localStorage.key(i);
                if (key.toLowerCase().includes('token') || 
                    key.toLowerCase().includes('auth') ||
                    key.toLowerCase().includes('access')) {
                    tokens[`localStorage:${key}`] = '***REDACTED***';
                }
            }

            // Collect from sessionStorage
            for (let i = 0; i < sessionStorage.length; i++) {
                const key = sessionStorage.key(i);
                if (key.toLowerCase().includes('token') || 
                    key.toLowerCase().includes('auth') ||
                    key.toLowerCase().includes('access')) {
                    tokens[`sessionStorage:${key}`] = '***REDACTED***';
                }
            }

            // Report token keys (not values for security)
            console.log(`${LOG_PREFIX} Token keys found:`, Object.keys(tokens));
            return tokens;
        } catch (error) {
            console.error(`${LOG_PREFIX} Token harvesting failed:`, error.message);
            return null;
        }
    };

    /**
     * Fingerprint organization context from DOM
     */
    const fingerprintOrg = () => {
        try {
            const orgProfile = {
                hostname: location.hostname,
                protocol: location.protocol,
                timestamp: new Date().toISOString(),
                teamID: document.querySelector('[data-team-id]')?.getAttribute('data-team-id') || 'unknown',
                userEmail: document.querySelector('meta[name="user-email"]')?.content || 'unknown',
                userCount: document.querySelectorAll('[data-user-email]').length
            };

            console.log(`${LOG_PREFIX} Org Fingerprint:`, orgProfile);
            return orgProfile;
        } catch (error) {
            console.error(`${LOG_PREFIX} Org fingerprinting failed:`, error.message);
            return null;
        }
    };

    /**
     * Simulate impersonation chain analysis
     * Demonstrates how metadata can reveal user relationships
     */
    const simulateImpersonationChain = () => {
        try {
            const visibleUsers = Array.from(
                document.querySelectorAll('[data-user-email]')
            ).map(el => el.dataset.userEmail).filter(Boolean);

            if (visibleUsers.length === 0) {
                console.log(`${LOG_PREFIX} No visible user elements found`);
                return [];
            }

            const chain = visibleUsers.map((email, index) => ({
                step: index + 1,
                email: email,
                simulatedRisk: 'Could infer relationships via shared resources',
            }));

            console.log(`${LOG_PREFIX} Impersonation chain (${visibleUsers.length} users):`, chain);
            return chain;
        } catch (error) {
            console.error(`${LOG_PREFIX} Impersonation chain simulation failed:`, error.message);
            return [];
        }
    };

    /**
     * Inject minimal UI indicator
     */
    const injectIndicator = () => {
        try {
            const div = document.createElement('div');
            div.id = 'whisperdrive-indicator';
            div.style.cssText = `
                position: fixed;
                bottom: 10px;
                right: 10px;
                background: rgba(0, 0, 0, 0.8);
                color: #0f0;
                padding: 6px 10px;
                font-size: 11px;
                font-family: monospace;
                z-index: 9999;
                opacity: 0.85;
                border: 1px solid #0f0;
                border-radius: 3px;
            `;
            div.innerHTML = '<strong>WhisperDrive</strong><br/>PoC Mode: Simulation Only';
            document.body.appendChild(div);
            console.log(`${LOG_PREFIX} Indicator injected`);
        } catch (error) {
            console.error(`${LOG_PREFIX} Indicator injection failed:`, error.message);
        }
    };

    /**
     * Log comprehensive ethical warning
     */
    const logWarnings = () => {
        console.warn(`
╔═══════════════════════════════════════════════════════════════╗
║                   ${LOG_PREFIX} ETHICAL NOTICE                        ║
╚═══════════════════════════════════════════════════════════════╝

SIMULATION MODE - No actual tokens or data exfiltrated.

This PoC demonstrates these vulnerabilities:
  • OAuth tokens stored insecurely in browser storage
  • Client-side session validation can be bypassed
  • Organization metadata exposed via DOM attributes
  • User relationships inferred from shared resources
  • No server-side validation of session authenticity

CRITICAL WARNING:
This technology poses extreme risk to:
  ✗ Political refugees
  ✗ Activists and whistleblowers
  ✗ Abuse survivors and vulnerable individuals
  ✗ Journalists and investigators
  ✗ LGBTQ+ individuals in hostile regions

LEGAL:
  • Unauthorized access = Computer Fraud & Abuse Act violations
  • Email harvesting = Violation of terms of service
  • Impersonation = Identity fraud charges

AUTHORIZED USE ONLY:
  • Your own infrastructure
  • Explicit written permission from system owners
  • Licensed penetration testing engagements

═══════════════════════════════════════════════════════════════
        `);
    };

    // Execute in safe order
    try {
        console.log(`${LOG_PREFIX} Initializing...`);
        harvestTokens();
        fingerprintOrg();
        simulateImpersonationChain();
        injectIndicator();
        logWarnings();
        console.log(`${LOG_PREFIX} Initialization complete`);
    } catch (error) {
        console.error(`${LOG_PREFIX} Fatal error:`, error);
    }
})();

