        error: (...args) => console.error(PREFIX, ...args)
    };

    /**
     * Safely extract token keys (not values) from storage
     * Values are NEVER logged or transmitted
     */
    const harvestTokenKeys = () => {
        try {
            const tokenKeys = {
                localStorage: [],
                sessionStorage: [],
                foundTokens: false
            };

            // Scan localStorage for token-like keys
            for (let i = 0; i < localStorage.length; i++) {
                const key = localStorage.key(i);
                if (isTokenLikeKey(key)) {
                    tokenKeys.localStorage.push(key);
                    tokenKeys.foundTokens = true;
                }
            }

            // Scan sessionStorage for token-like keys
            for (let i = 0; i < sessionStorage.length; i++) {
                const key = sessionStorage.key(i);
