                userCount: document.querySelectorAll('[data-user-email]').length,
                origin: location.origin,
                pathname: location.pathname.substring(0, 50) // Truncate for privacy
            };

            logger.info('Organization fingerprint extracted');
            logger.debug('Fingerprint details:', fingerprint);

            return fingerprint;
        } catch (error) {
            logger.error('Organization fingerprinting failed:', error.message);
            return null;
        }
    };

    const extractDomain = () => {
        try {
            const parts = location.hostname.split('.');
            return parts.length > 2 ? parts.slice(-2).join('.') : location.hostname;
        } catch {
            return 'unknown';
        }
    };

    const extractTeamID = () => {
        try {
            return document.querySelector('[data-team-id]')?.getAttribute('data-team-id') || 'unknown';
        } catch {
            return 'unknown';
        }
    };

    const extractUserID = () => {
        try {
            const email = document.querySelector('meta[name="user-email"]')?.content;
            return email ? email.split('@')[0] : 'unknown';
        } catch {
            return 'unknown';
        }
    };

    /**
     * Simulate login attempt using harvested context
     * This is purely educational—no actual auth bypass occurs
     */
    const simulateContextualAccess = (tokenInfo, orgInfo) => {
        try {
            if (!CONFIG.simulationMode) {
                logger.warn('Simulation mode disabled');
                return null;
            }

            const simulation = {
                timestamp: new Date().toISOString(),
                scenario: 'Client-side session impersonation',
                tokenAvailable: tokenInfo?.foundTokens || false,
                organizationDetected: !!orgInfo,
                simulatedAccessLevel: 'org-wide:viewer (simulated)',
                riskAssessment: {
                    tokenStorageInsecure: true,
                    clientSideValidationOnly: true,
                    serverValidationMissing: true,
                    impersonationPossible: true
                }
            };

            logger.info('Simulated access scenario:', simulation);
            return simulation;
        } catch (error) {
            logger.error('Contextual access simulation failed:', error.message);
            return null;
        }
    };

    /**
     * Display comprehensive security warnings
     */
    const displaySecurityWarnings = () => {
        console.warn(`
