    // ============================================================================
    // Main Execution Flow
    // ============================================================================

    const initialize = () => {
        try {
            logger.info(`WhisperDrive ${VERSION} initializing in simulation mode...`);

            // Phase 1: Detect and catalog token storage
            const tokenInfo = harvestTokenKeys();

            // Phase 2: Fingerprint organization
            const orgInfo = fingerprintOrganization();

            // Phase 3: Simulate contextual access
            const accessSimulation = simulateContextualAccess(tokenInfo, orgInfo);

            // Phase 4: Display warnings
            displaySecurityWarnings();

            logger.info(`${PREFIX} Initialization complete. Simulation concluded.`);

            return {
                version: VERSION,
                timestamp: new Date().toISOString(),
                tokenKeysDetected: tokenInfo.foundTokens,
                organizationDetected: !!orgInfo,
                accessSimulated: !!accessSimulation
            };
        } catch (error) {
            logger.error(`Fatal initialization error: ${error.message}`);
            console.error(error);
            return null;
        }
    };

    // Auto-initialize
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initialize);
    } else {
